import{_ as e,o as r,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"优先级 1","description":"","frontmatter":{},"headers":[],"relativePath":"skill/priority.md","filePath":"skill/priority.md","lastUpdated":null}'),t={name:"skill/priority.md"};function o(h,a,n,s,d,p){return r(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="优先级-1" tabindex="-1">优先级 <a href="https://www.bilibili.com/video/BV1254y1D7Ht?from=search&amp;seid=14167562900175777805" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#优先级-1" aria-label="Permalink to &quot;优先级 [1]&quot;">​</a></h1><h2 id="why-2" tabindex="-1">why? <a href="https://zhuanlan.zhihu.com/p/22067195" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#why-2" aria-label="Permalink to &quot;why? [2]&quot;">​</a></h2><p>人类拥有无穷的欲望，却只拥有有限的资源。熊掌与鱼，不可兼得！</p><h2 id="对「优先级」的定义关系产品成败" tabindex="-1">对「优先级」的定义关系产品成败 <a class="header-anchor" href="#对「优先级」的定义关系产品成败" aria-label="Permalink to &quot;对「优先级」的定义关系产品成败&quot;">​</a></h2><p>苹果早期 iPhone 的设计是优先级控制的典范。手机正面只有一个按键的设计，尽管现在看来似乎是理所当然的，但在当时却是非常勇敢和有争议的决定。我曾深入研究过 iOS 系统早期的设计，在很多地方的取舍做的非常到位，能够大胆砍掉之前手机系统常见的功能和界面元素，让重点变得更重点，让需要突出的内容变得更突出。</p><p>而相比之下，同一时期诺基亚的系统尽管拥有大量功能，在呈现给用户时并没有处理好优先级，对于用户相对要更复杂，如果读者还有印象，可以想象一下打开一个联系人，看看与之对应的常常的功能菜单。而那个时候微软的 Windows Mobile 系统，则是大量将 PC 上的体验搬到手机上，用户的认知资源和系统有限的显示和交互资源之间并不匹配。</p><h2 id="结构化优先级" tabindex="-1">结构化优先级 <a class="header-anchor" href="#结构化优先级" aria-label="Permalink to &quot;结构化优先级&quot;">​</a></h2><ol><li>信息优先级要关注内容的组织关系和轻重缓急</li><li>视觉优先级重在引导用户视线和行为轨迹</li><li>交互优先级要区分主线和支线任务</li><li>需求优先级要平衡用户目标和商业目标</li><li>用户优先级要界定核心用户是谁</li></ol><h3 id="信息优先级" tabindex="-1">信息优先级 <a class="header-anchor" href="#信息优先级" aria-label="Permalink to &quot;信息优先级&quot;">​</a></h3><p>余额宝：收益、总金额。字号大，想让你看！麦肯兹金字塔。</p><h3 id="视觉优先级" tabindex="-1">视觉优先级 <a class="header-anchor" href="#视觉优先级" aria-label="Permalink to &quot;视觉优先级&quot;">​</a></h3><ul><li>报纸上的文字大小、颜色、区块</li><li>海报朝着商品上看。</li></ul><h3 id="交互优先级" tabindex="-1">交互优先级 <a class="header-anchor" href="#交互优先级" aria-label="Permalink to &quot;交互优先级&quot;">​</a></h3><p>区分主线和支线，<strong>突出主线任务</strong></p><ul><li>读书app，点一下会设置，再点一下只能前后。读书！</li><li>支付宝，收付钱。</li><li>滴滴，预约用车、现在用车。感觉车很多。</li></ul><p>建立故事，记忆更深刻。</p><p>豌豆荚几亿钱分十几个人！</p><h3 id="需求优先级" tabindex="-1">需求优先级 <a class="header-anchor" href="#需求优先级" aria-label="Permalink to &quot;需求优先级&quot;">​</a></h3><p>需求优先级要平衡用户目标和商业目标。</p><ul><li>用户目标：炫耀。读取型号、找对应图片、程序合成</li><li>商业目标：更多用户。使用豌豆荚截图+<strong>网址</strong>。留个空间给裁。</li></ul><h2 id="项目范围优先级制定一沟通计划" tabindex="-1">项目范围优先级制定一沟通计划 <a class="header-anchor" href="#项目范围优先级制定一沟通计划" aria-label="Permalink to &quot;项目范围优先级制定一沟通计划&quot;">​</a></h2><p>By who、Who、How、Why、When、What。</p><p>制定沟通计划的目的是为项目交付周期的交流和相互支持提供指导。在敏捷项目里,面对面交流比文档要好,但是依然会有一些共享文件,比如报告和项目计划,需要留下档案。</p><h2 id="四象限-3" tabindex="-1">四象限 <a href="https://www.bilibili.com/video/BV1254y1D7Ht?from=search&amp;seid=14167562900175777805" target="_blank" rel="noreferrer">3</a> <a class="header-anchor" href="#四象限-3" aria-label="Permalink to &quot;四象限 [3]&quot;">​</a></h2><p>优先级顺序:重要、紧急（立即做）&gt;重要、不紧急（时间表）&gt;不重要、紧急（委派）&gt;不重要、不紧急（排除）</p>',25)])])}const b=e(t,[["render",o]]);export{u as __pageData,b as default};
